/**
 * @file macho.c
 * @brief 32-bit Mach-O loader (MH_EXECUTE, ARMv6 / ARMv7) for PlayStation Vita.
 * @details
 * 1. One VM-domain image preserves __TEXT/__DATA distance and one runtime slide.
 *    Allocation alone does not prove RX/cache readiness; execution stays gated.
 * 2. rebase.bin (generated by tools/macho_prep.py) lists absolute __DATA pointers to relocate with macho_slide.
 * 3. Imports: resolves dynamic imports intercepting calls to iOS / Darwin / UIKit libraries.
 *    Required unresolved symbols fail closed; no zero-returning fallback thunks.
 */
#include <kubridge.h>
#include <psp2/kernel/sysmem.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "imports.h"
#include "log.h"
#include "macho.h"
#include "macho_reloc.h"
#include "macho_name.h"
#include "macho_init.h"
#include "objc_guest.h"
#include "foundation.h"
#include "cfstring.h"
#include "macho_layout.h"

#define LC_SEGMENT 0x1
#define LC_SYMTAB 0x2
#define LC_DYSYMTAB 0xB
#define LC_ENCRYPTION_INFO 0x21

#define S_ZEROFILL 0x1
#define S_NON_LAZY_SYMBOL_POINTERS 0x6
#define S_LAZY_SYMBOL_POINTERS 0x7

#define INDIRECT_SYMBOL_LOCAL 0x80000000u
#define INDIRECT_SYMBOL_ABS 0x40000000u

#define N_STAB 0xE0
#define N_TYPE 0x0E
#define N_SECT 0x0E
#define N_ARM_THUMB_DEF 0x0008

#define THUNK_ARENA_SIZE 0x20000

typedef struct {
    uint32_t cmd, cmdsize;
    char segname[16];
    uint32_t vmaddr, vmsize, fileoff, filesize, maxprot, initprot, nsects, flags;
} segment_command;

typedef struct {
    char sectname[16], segname[16];
    uint32_t addr, size, offset, align, reloff, nreloc, flags, reserved1, reserved2;
} section;

typedef struct {
    uint32_t n_strx;
    uint8_t n_type, n_sect;
    uint16_t n_desc;
    uint32_t n_value;
} nlist;

typedef struct {
    uint32_t ilocalsym, nlocalsym, iextdefsym, nextdefsym, iundefsym, nundefsym, tocoff, ntoc,
        modtaboff, nmodtab, extrefsymoff, nextrefsyms, indirectsymoff, nindirectsyms, extreloff,
        nextrel, locreloff, nlocrel;
} dysymtab_command;

static uint8_t *image_raw; /* Retained while symbol/string tables borrow it. */
static nlist *symtab;
static uint32_t nsyms;
static uint32_t strtab_size;
static const char *strtab;
static uint32_t text_vm, text_size, data_vm, data_size;
static uint32_t code_vm,code_size;
static uint8_t *text_buf;
static uintptr_t text_real;
static uint32_t macho_slide;
static int guest_exec_ready;
static SceUID image_blk = -1;
static uint32_t mod_init_addr, mod_init_count;

static uint32_t *thunk_head, *thunk_end;
static SceUID thunk_blk = -1;
extern void ml_align_call(void);

uint32_t macho_get_runtime_slide(void) { return macho_slide; }

static uintptr_t make_thunk(uint32_t ip_value, void *jump) {
    if (thunk_head + 4 > thunk_end)
        fatal_error("Thunk arena exhausted");
    uint32_t code[4] = {
        0xE59FC000, // ldr ip, [pc, #0]
        0xE59FF000, // ldr pc, [pc, #0]
        ip_value,
        (uint32_t)(uintptr_t)jump,
    };
    uintptr_t addr = (uintptr_t)thunk_head;
    kuKernelCpuUnrestrictedMemcpy(thunk_head, code, sizeof(code));
    kuKernelFlushCaches(thunk_head, sizeof(code));
    thunk_head += 4;
    return addr;
}

uintptr_t macho_sym(const char *name) {
    if (!symtab || !strtab)
        return 0;
    for (uint32_t i = 0; i < nsyms; i++) {
        nlist *s = &symtab[i];
        if (s->n_strx >= strtab_size ||
            !memchr(strtab + s->n_strx, 0, strtab_size - s->n_strx))
            continue;
        if (s->n_type & N_STAB)
            continue;
        if ((s->n_type & N_TYPE) != N_SECT)
            continue;
        if (!strcmp(strtab + s->n_strx, name)) {
            const uint32_t va = s->n_value & ~1u;
            const int valid_text = va >= text_vm &&
                (uint64_t)va < (uint64_t)text_vm + text_size;
            const int valid_data = va >= data_vm &&
                (uint64_t)va < (uint64_t)data_vm + data_size;
            if (!valid_text && !valid_data) {
                l_error("Symbol %s points outside mapped Mach-O VM: 0x%08X",
                        name, (unsigned)s->n_value);
                return 0;
            }
            uintptr_t a = macho_slide + va;
            if ((s->n_desc & N_ARM_THUMB_DEF) || (s->n_value & 1u))
                a |= 1u;
            return a;
        }
    }
    return 0;
}

void macho_hook(const char *name, void *dst) {
    if (!guest_exec_ready) {
        l_error("macho_hook blocked: guest execution not verified");
        return;
    }
    uintptr_t a = macho_sym(name);
    if (a & 1u) {
        l_error("macho_hook cannot write ARM trampoline over Thumb code");
        return;
    }
    if (!a) {
        l_warn("macho_hook: symbol '%s' not found", name);
        return;
    }
    uint32_t code[4] = {
        0xE59FC000, // ldr ip, [pc, #0]
        0xE59FF000, // ldr pc, [pc, #0]
        (uint32_t)(uintptr_t)dst,
        (uint32_t)(uintptr_t)dst,
    };
    kuKernelCpuUnrestrictedMemcpy((void *)(a & ~1), code, sizeof(code));
    kuKernelFlushCaches((void *)(a & ~1), sizeof(code));
}

typedef struct { unsigned unresolved_objc_classes,unresolved_other; } ExternalContext;
static uint8_t *external_word(void *ctx,uint32_t va) {
    (void)ctx;
    if(va>=text_vm && (uint64_t)va+4u<=(uint64_t)text_vm+text_size)
        return text_buf+(va-text_vm);
    if(va>=data_vm && (uint64_t)va+4u<=(uint64_t)data_vm+data_size)
        return (uint8_t *)(uintptr_t)(macho_slide+va);
    return NULL;
}
static int external_symbol(void *opaque,uint32_t idx,uint32_t *address) {
    ExternalContext *ctx=opaque;
    if(idx>=nsyms || symtab[idx].n_strx>=strtab_size) return -1;
    const char *name=strtab+symtab[idx].n_strx;
    if(!memchr(name,0,strtab_size-symtab[idx].n_strx)) return -1;
    int is_class=!strncmp(name,"_OBJC_CLASS_$_",14) || !strncmp(name,"_OBJC_METACLASS_$_",18);
    const import_entry *imp=imports_lookup(name);
    if(imp && (!is_class || imp->data==IM2_IMPORT_DATA)) {
        if(imp->data<IM2_IMPORT_FUNCTION || imp->data>IM2_IMPORT_ABI_ENTRY) return -1;
        *address=imp->data?imp->addr:make_thunk(imp->addr,ml_align_call);return 0;
    }
    uintptr_t guest=macho_sym(name);
    if(guest) {*address=(uint32_t)guest;return 0;}
    if(is_class) ctx->unresolved_objc_classes++;else ctx->unresolved_other++;
    l_warn("Unresolved required external relocation: %s",name);return -1;
}

static int apply_rebase(const char *rebase_path,const dysymtab_command *dynamic,const uint8_t *slice,size_t slice_size) {
    if (!rebase_path)
        return -1;
    FILE *f = fopen(rebase_path, "rb");
    if (!f) {
        l_error("Required RBS1 table missing: %s", rebase_path);
        return -1;
    }
    uint32_t magic = 0, count = 0;
    if (fread(&magic, 4, 1, f) != 1 || magic != 0x31534252u ||
        fread(&count, 4, 1, f) != 1) {
        l_error("Invalid RBS1 header");
        fclose(f);
        return -1;
    }
    const uint64_t vm_span = (uint64_t)data_vm + data_size - text_vm;
    if (!count || (uint64_t)count > vm_span / 4u || count > 1000000u) {
        l_error("Impossible RBS1 entry count: %u", (unsigned)count);
        fclose(f);
        return -1;
    }
    uint32_t *entries = malloc((size_t)count * sizeof(uint32_t));
    if (!entries) {
        fclose(f);
        return -1;
    }
    if (fread(entries, sizeof(uint32_t), count, f) != count || fgetc(f) != EOF) {
        l_error("Truncated or trailing RBS1 data");
        free(entries);
        fclose(f);
        return -1;
    }
    fclose(f);

    if(dynamic && (uint64_t)dynamic->extreloff+(uint64_t)dynamic->nextrel*8u>slice_size) {
        free(entries);return -1;
    }
    // Validate ALL addresses before touching image memory.
    // Iron Man 2's generated RBS1 is sorted, unique and word-aligned.
    uint32_t previous = 0;
    for (uint32_t i = 0; i < count; i++) {
        const uint32_t va = entries[i];
        const int in_text = va >= text_vm &&
            (uint64_t)va + 4u <= (uint64_t)text_vm + text_size;
        const int in_data = va >= data_vm &&
            (uint64_t)va + 4u <= (uint64_t)data_vm + data_size;
        if ((va & 3u) || (i && va <= previous) || (!in_text && !in_data)) {
            l_error("RBS1 invalid address at %u: 0x%08X",
                    (unsigned)i, (unsigned)va);
            free(entries);
            return -1;
        }
        // Every relocation payload must still reference the original guest image.
        // Reject malformed pointers and arithmetic overflow before mutating ANY slot.
        const uint32_t value = in_data ?
            *(uint32_t *)(uintptr_t)(macho_slide + va) :
            *(uint32_t *)(text_buf + (va - text_vm));
        const uint32_t target_va = value & ~1u;
        if (target_va < text_vm ||
            (uint64_t)target_va >= (uint64_t)data_vm + data_size ||
            (uint64_t)value + macho_slide > UINT32_MAX) {
            l_error("RBS1 pointer payload invalid at 0x%08X: 0x%08X",
                    (unsigned)va, (unsigned)value);
            free(entries);
            return -1;
        }
        previous = va;
    }
    // The validated RBS1 is sorted; reject external overlap in O(R log N).
    if(dynamic) for(uint32_t i=0;i<dynamic->nextrel;i++) {
        uint32_t address;memcpy(&address,slice+dynamic->extreloff+8u*i,4);
        uint32_t lo=0,hi=count;
        while(lo<hi) {uint32_t mid=lo+(hi-lo)/2;if(entries[mid]<address)lo=mid+1;else hi=mid;}
        if(lo<count && entries[lo]==address) {
            l_error("RBS1 overlaps external relocation at 0x%08X",(unsigned)address);
            free(entries);return -1;
        }
    }
    for (uint32_t i = 0; i < count; i++) {
        const uint32_t va = entries[i];
        uint32_t *ptr = va >= data_vm ?
            (uint32_t *)(uintptr_t)(macho_slide + va) :
            (uint32_t *)(text_buf + (va - text_vm));
        *ptr += macho_slide;
    }
    free(entries);
    l_info("RBS1 validated and applied: %u relocation words", (unsigned)count);
    return 0;
}

static const uint8_t *read_guest_metadata(void *context,uint32_t address,size_t bytes,int executable) {
    (void)context;
    if(address<macho_slide) return NULL;
    uint32_t vm=address-macho_slide;
    if(executable && (!code_size || vm<code_vm || (uint64_t)vm+bytes>(uint64_t)code_vm+code_size)) return NULL;
    if(vm>=text_vm && (uint64_t)vm+bytes<=(uint64_t)text_vm+text_size) return text_buf+(vm-text_vm);
    if(!executable && vm>=data_vm && (uint64_t)vm+bytes<=(uint64_t)data_vm+data_size) return (const uint8_t *)(uintptr_t)address;
    return NULL;
}
uintptr_t macho_entry(const char *name) {
    uintptr_t fn=macho_sym(name),pc=fn&~(uintptr_t)1u;
    if(!fn || !code_size || (pc&((fn&1u)?1u:3u)) ||
       pc<(uint64_t)macho_slide+code_vm || pc+((fn&1u)?2u:4u)>(uint64_t)macho_slide+code_vm+code_size) return 0;
    return fn;
}

int macho_load(const char *bin_path, const char *rebase_path) {
    /* No teardown/reload of a retained image with registered borrowed identities. */
    if (image_blk >= 0 || image_raw) return -1;
    FILE *f = NULL;
    uint8_t *raw = NULL;
    size_t class_checkpoint = 0;
    int class_registration_started = 0, constants_registered = 0;
    guest_exec_ready = 0;
    macho_slide = 0;
    mod_init_addr = 0;
    mod_init_count = 0;
    code_vm=code_size=0;
    l_info("Loading Mach-O executable: %s", bin_path);
    f = fopen(bin_path, "rb");
    if (!f)
        goto failed;
    if (fseek(f, 0, SEEK_END) != 0) {
        goto failed;
    }
    long len = ftell(f);
    if (len < 28 || fseek(f, 0, SEEK_SET) != 0) {
        goto failed;
    }
    size_t file_len = (size_t)len;

    raw = malloc(file_len);
    if (!raw)
        goto failed;
    if (fread(raw, 1, file_len, f) != file_len) {
        goto failed;
    }
    fclose(f); f = NULL;

    uint8_t *d = raw;
    size_t slice_len = file_len;

    // Detect FAT universal Mach-O (big-endian 0xCAFEBABE)
    if (file_len >= 8 && (memcmp(raw, "\xca\xfe\xba\xbe", 4) == 0 || memcmp(raw, "\xbe\xba\xfe\xca", 4) == 0)) {
        uint32_t nfat = (raw[4] << 24) | (raw[5] << 16) | (raw[6] << 8) | raw[7];
        if (nfat > (file_len - 8u) / 20u) {
            goto failed;
        }
        uint32_t chosen_offset = 0, chosen_size = 0;
        const char *arch_name = "arm";
        for (uint32_t i = 0; i < nfat; i++) {
            const uint8_t *arch_ptr = raw + 8 + i * 20;
            uint32_t cputype = (arch_ptr[0] << 24) | (arch_ptr[1] << 16) | (arch_ptr[2] << 8) | arch_ptr[3];
            uint32_t cpusub = (arch_ptr[4] << 24) | (arch_ptr[5] << 16) | (arch_ptr[6] << 8) | arch_ptr[7];
            uint32_t off = (arch_ptr[8] << 24) | (arch_ptr[9] << 16) | (arch_ptr[10] << 8) | arch_ptr[11];
            uint32_t sz = (arch_ptr[12] << 24) | (arch_ptr[13] << 16) | (arch_ptr[14] << 8) | arch_ptr[15];
            if (cputype == 12 /* CPU_TYPE_ARM */) {
                if (cpusub == 9 /* v7 */ || cpusub == 11 /* v7s */) {
                    chosen_offset = off;
                    chosen_size = sz;
                    arch_name = "armv7";
                    break;
                } else if (cpusub == 6 /* v6 */ && !chosen_offset) {
                    chosen_offset = off;
                    chosen_size = sz;
                    arch_name = "armv6";
                }
            }
        }
        if (chosen_offset && (uint64_t)chosen_offset + chosen_size <= file_len) {
            l_info("FAT binary detected: selected slice %s (offset 0x%X, size %u KB)",
                   arch_name, (unsigned)chosen_offset, (unsigned)(chosen_size / 1024));
            d = raw + chosen_offset;
            slice_len = chosen_size;
        }
    }

    if (slice_len < 28u) {
        goto failed;
    }
    uint32_t magic = *(uint32_t *)d;
    if (magic != 0xFEEDFACE)
        goto failed;

    uint32_t ncmds = *(uint32_t *)(d + 16);
    uint32_t sizeofcmds = *(uint32_t *)(d + 20);
    if (ncmds > sizeofcmds / 8u || (uint64_t)28u + sizeofcmds > slice_len) {
        l_error("Invalid Mach-O load command envelope");
        goto failed;
    }
    uint32_t off = 28;

    dysymtab_command *dysym = NULL;
    segment_command *seg_text = NULL, *seg_data = NULL;
    section *sects[64];
    int nsects_total = 0;

    for (uint32_t c = 0; c < ncmds; c++) {
        if ((uint64_t)off + 8u > (uint64_t)28u + sizeofcmds) {
            l_error("Mach-O load command header truncated");
            goto failed;
        }
        uint32_t cmd = *(uint32_t *)(d + off);
        uint32_t size = *(uint32_t *)(d + off + 4);
        if (size < 8u || (uint64_t)off + size > (uint64_t)28u + sizeofcmds) {
            l_error("Mach-O load command extends beyond command region");
            goto failed;
        }
        if (cmd == LC_SEGMENT) {
            if (size < 56u) goto failed;
            segment_command *s = (segment_command *)(d + off);
            if (im2_macho_name_equal(s->segname, "__TEXT"))
                seg_text = s;
            else if (im2_macho_name_equal(s->segname, "__DATA"))
                seg_data = s;
            if (s->nsects > (size - 56u) / sizeof(section))
                goto failed;
            section *sec = (section *)(d + off + 56);
            if (s->nsects > 64u - (uint32_t)nsects_total) goto failed;
            for (uint32_t i = 0; i < s->nsects; i++)
                sects[nsects_total++] = &sec[i];
        } else if (cmd == LC_SYMTAB) {
            if (size < 24u) goto failed;
            uint32_t *p = (uint32_t *)(d + off + 8);
            if ((uint64_t)p[0] + (uint64_t)p[1] * sizeof(nlist) > slice_len ||
                (uint64_t)p[2] + p[3] > slice_len)
                goto failed;
            symtab = (nlist *)(d + p[0]);
            nsyms = p[1];
            strtab = (const char *)(d + p[2]);
            strtab_size = p[3];
        } else if (cmd == LC_DYSYMTAB) {
            if (size < 80u) goto failed;
            dysym = (dysymtab_command *)(d + off + 8);
            if ((uint64_t)dysym->indirectsymoff +
                    (uint64_t)dysym->nindirectsyms * 4u > slice_len)
                goto failed;
        } else if (cmd == LC_ENCRYPTION_INFO) {
            // encryption_info_command is 20 bytes, including cmd/cmdsize.
            if (size < 20u) {
                l_error("Truncated Mach-O encryption command");
                goto failed;
            }
            uint32_t cryptoff = *(uint32_t *)(d + off + 8);
            uint32_t cryptsize = *(uint32_t *)(d + off + 12);
            uint32_t cryptid = *(uint32_t *)(d + off + 16);
            if ((uint64_t)cryptoff + cryptsize > slice_len) {
                l_error("Mach-O encryption region outside file");
                goto failed;
            }
            if (cryptid != 0) {
                l_error("================================================================");
                l_error("CRITICAL ALERT: Binary contains FairPlay DRM encryption (cryptid %u)!", (unsigned)cryptid);
                l_error("Cannot execute encrypted binary on PS Vita. Must be decrypted first.");
                goto failed;
            }
        }
        off += size;
    }

    if (!seg_text || !seg_data)
        goto failed;
    Im2MachoLayout layout;
    if (im2_macho_layout(seg_text->vmaddr, seg_text->vmsize,
            seg_text->fileoff, seg_text->filesize, seg_data->vmaddr,
            seg_data->vmsize, seg_data->fileoff, seg_data->filesize,
            slice_len, &layout)) {
        l_error("Invalid/oversized contiguous Mach-O segment layout");
        goto failed;
    }
    text_vm = seg_text->vmaddr;
    text_size = layout.text_size;
    data_vm = seg_data->vmaddr;
    data_size = layout.data_size;
    // Preserve original __TEXT/__DATA distance; never allocate segments separately.
    const uint32_t image_span = layout.span;
    image_blk = sceKernelAllocMemBlockForVM("macho_image", image_span);
    if (image_blk < 0)
        goto failed;
    void *text_ptr = NULL;
    if (sceKernelGetMemBlockBase(image_blk, &text_ptr) < 0 || !text_ptr)
        goto failed;
    text_real = (uintptr_t)text_ptr;
    if (text_real < text_vm || (uint64_t)text_real + image_span > UINT32_MAX)
        goto failed;
    macho_slide = (uint32_t)(text_real - text_vm);
    void *data_ptr = (void *)(text_real + (data_vm - text_vm));
    l_info("Mach-O image base=%p runtime_slide=0x%08X span=0x%X",
           text_ptr, (unsigned)macho_slide, (unsigned)image_span);

    // Executable thunk arena
    thunk_blk = sceKernelAllocMemBlockForVM("macho_thunks", THUNK_ARENA_SIZE);
    void *thunk_ptr = NULL;
    if (thunk_blk < 0 ||
        sceKernelGetMemBlockBase(thunk_blk, &thunk_ptr) < 0 || !thunk_ptr) {
        l_error("Cannot allocate executable import thunk arena");
        goto failed;
    }
    thunk_head = (uint32_t *)thunk_ptr;
    thunk_end = thunk_head + (THUNK_ARENA_SIZE / 4);

    // Copy segment contents
    text_buf = malloc(text_size);
    if (!text_buf) {
        l_error("Cannot allocate temporary Mach-O __TEXT buffer");
        goto failed;
    }
    memset(text_buf, 0, text_size);
    memcpy(text_buf, d + seg_text->fileoff, seg_text->filesize);

    memset(data_ptr, 0, data_size);
    memcpy(data_ptr, d + seg_data->fileoff, seg_data->filesize);

    // Initialize special sections
    for (int i = 0; i < nsects_total; i++) {
        section *s = sects[i];
        if(im2_macho_name_equal(s->sectname,"__text")) {
            if(code_size || !s->size || s->addr<text_vm || (uint64_t)s->addr+s->size>(uint64_t)text_vm+text_size) goto failed;
            code_vm=s->addr;code_size=s->size;
        }
        if (im2_macho_name_equal(s->sectname, "__mod_init_func")) {
            if(mod_init_addr) goto failed;
            if ((s->size & 3u) || s->addr < data_vm ||
                (uint64_t)s->addr + s->size > (uint64_t)data_vm + data_size)
                goto failed;
            mod_init_addr = macho_slide + s->addr;
            mod_init_count = s->size / 4;
        }
    }

    // Rebase original local pointers BEFORE overwriting imported symbol slots.
    if (apply_rebase(rebase_path,dysym,d,slice_len) != 0)
        goto failed;

    // ObjC classrefs are S_REGULAR in the original Iron Man 2 Mach-O.
    // Resolve their external relocations from LC_DYSYMTAB; indirect pointers
    // alone do NOT cover these class objects.
    ExternalContext external={0,0};
    if(dysym) {
        if((uint64_t)dysym->extreloff+(uint64_t)dysym->nextrel*8u>slice_len) goto failed;
        char error[160];
        if(im2_apply_external_relocs(d+dysym->extreloff,dysym->nextrel,nsyms,
            external_word,external_symbol,&external,error,sizeof(error))) {
            if(external.unresolved_objc_classes) l_error("Unresolved ObjC class/metaclass relocations");
            l_error("External relocation rejected: %s",error);goto failed;
        }
    }

    // Validate the actual ObjC pointer sections after external relocations.
    // A missing/unsupported relocation must not leave a nil classref behind.
    for (int sec_idx = 0; sec_idx < nsects_total; sec_idx++) {
        const section *sec = sects[sec_idx];
        if (!im2_macho_name_equal(sec->sectname, "__objc_classrefs") &&
            !im2_macho_name_equal(sec->sectname, "__objc_superrefs"))
            continue;
        if ((sec->size & 3u) || sec->addr < data_vm ||
            (uint64_t)sec->addr + sec->size > (uint64_t)data_vm + data_size)
            goto failed;
        const uint32_t *refs = (const uint32_t *)(uintptr_t)(macho_slide + sec->addr);
        for (uint32_t i = 0; i < sec->size / 4u; i++) {
            if (!refs[i]) {
                l_error("Unbound ObjC class reference at 0x%08X",
                        (unsigned)(sec->addr + i * 4u));
                goto failed;
            }
        }
    }

    // Resolve dynamic symbol imports. Unknown iOS APIs are fatal to readiness:
    // a zero-returning fallback thunk would hide a broken compatibility layer.
    unsigned unresolved_imports = 0;
    if (dysym) {
        uint32_t *indirect = (uint32_t *)(d + dysym->indirectsymoff);
        for (int s_idx = 0; s_idx < nsects_total; s_idx++) {
            section *s = sects[s_idx];
            if ((s->flags & 0xffu) == S_NON_LAZY_SYMBOL_POINTERS || (s->flags & 0xffu) == S_LAZY_SYMBOL_POINTERS) {
                uint32_t nslots = s->size / 4;
                if ((s->size & 3u) || (uint64_t)s->reserved1 + nslots > dysym->nindirectsyms ||
                    s->addr < data_vm ||
                    (uint64_t)s->addr + s->size > (uint64_t)data_vm + data_size) {
                    l_error("Invalid indirect symbol section layout");
                    goto failed;
                }
                uint32_t *slots = (uint32_t *)(uintptr_t)(macho_slide + s->addr);
                for (uint32_t i = 0; i < nslots; i++) {
                    uint32_t sym_idx = indirect[s->reserved1 + i];
                    if (sym_idx & INDIRECT_SYMBOL_LOCAL) {
                        // The mandatory RBS1 table must have already relocated
                        // every local slot. Never relocate it a second time.
                        continue;
                    } else if (!(sym_idx & INDIRECT_SYMBOL_ABS)) {
                        if (!symtab || !strtab || sym_idx >= nsyms ||
                            symtab[sym_idx].n_strx >= strtab_size) {
                            l_error("Invalid Mach-O imported symbol index/string offset");
                            goto failed;
                        }
                        const char *name = strtab + symtab[sym_idx].n_strx;
                        if (!memchr(name, 0, strtab_size - symtab[sym_idx].n_strx))
                            goto failed;
                        const import_entry *imp = imports_lookup(name);
                        if (imp) {
                            if(imp->data<IM2_IMPORT_FUNCTION || imp->data>IM2_IMPORT_ABI_ENTRY) goto failed;
                            if (imp->data) {
                                slots[i] = imp->addr;
                            } else {
                                slots[i] = make_thunk(imp->addr, ml_align_call);
                            }
                        } else {
                            if (unresolved_imports < 20u)
                                l_warn("Unresolved required iOS import: %s", name);
                            unresolved_imports++;
                            slots[i] = 0;
                        }
                    }
                }
            }
        }
    }

    if (unresolved_imports) {
        l_error("Missing %u iOS import bindings; refusing guest execution",
                unresolved_imports);
        goto failed;
    }

    // Guest class metadata is consumed only after all symbol bindings are established.
    // Categories require explicit method merging; do not silently ignore their overrides.
    for(int i=0;i<nsects_total;i++) {
        const section *sec=sects[i];
        if(im2_macho_name_equal(sec->sectname,"__objc_catlist") && sec->size) {
            l_error("Objective-C categories not yet supported");goto failed;
        }
    }
    class_checkpoint=im2_objc_registration_checkpoint();
    class_registration_started=1;
    int classes_ok=1;
    char class_error[160]={0};
    for(int i=0;i<nsects_total;i++) {
        const section *sec=sects[i];
        if(!im2_macho_name_equal(sec->sectname,"__objc_classlist")) continue;
        if(sec->size%4u || sec->addr<data_vm ||
           (uint64_t)sec->addr+sec->size>(uint64_t)data_vm+data_size) {
            snprintf(class_error,sizeof(class_error),"invalid guest class-list section");classes_ok=0;break;
        }
        if(im2_objc_register_guest_list(macho_slide+sec->addr,sec->size/4u,
            read_guest_metadata,NULL,class_error,sizeof(class_error))) {classes_ok=0;break;}
    }
    // References can only be type-checked after local class identities are known.
    // A nonzero data/code pointer must never pass as a class/metaclass binding.
    if(classes_ok) for(int i=0;i<nsects_total;i++) {
        const section *sec=sects[i];
        if(!im2_macho_name_equal(sec->sectname,"__objc_classrefs") &&
           !im2_macho_name_equal(sec->sectname,"__objc_superrefs")) continue;
        if(im2_objc_validate_guest_refs(macho_slide+sec->addr,sec->size/4u,
            read_guest_metadata,NULL,class_error,sizeof(class_error))) {classes_ok=0;break;}
    }
    if(!classes_ok) {
        l_error("Guest Objective-C class/reference validation failed: %s",class_error);
        goto failed;
    }

    for(int i=0;i<nsects_total;i++) {
        const section *sec=sects[i];if(!im2_macho_name_equal(sec->sectname,"__cfstring"))continue;
        if(sec->size%16u || sec->addr<data_vm || (uint64_t)sec->addr+sec->size>(uint64_t)data_vm+data_size) goto failed;
        char error[160];
        if(im2_foundation_register_cfstrings(macho_slide+sec->addr,sec->size/16u,
            read_guest_metadata,NULL,error,sizeof(error))) {
            l_error("CFString constant registration rejected: %s",error);goto failed;
        }
        if(sec->size) constants_registered=1;
    }

    // Copy final __TEXT to executable memory block
    kuKernelCpuUnrestrictedMemcpy((void *)(uintptr_t)(macho_slide + text_vm), text_buf, text_size);
    kuKernelFlushCaches((void *)(uintptr_t)(macho_slide + text_vm), text_size);
    free(text_buf);
    text_buf = NULL;

    image_raw = raw;
    raw = NULL;
    // VM allocation does not prove executable permissions.
    // Fail closed until guest RX/cache coherence is verified on a Vita.
#ifdef IM2_ALLOW_UNVERIFIED_VM_EXEC
    l_warn("EXPERIMENTAL: executable permissions not independently verified");
    guest_exec_ready = 1;
    return 0;
#else
    l_error("Image mapped, but guest execution disabled until RX verification");
    return -2;
#endif
failed:
    if (f) fclose(f);
    guest_exec_ready = 0;
    /* Never free storage still referenced by identities if rollback itself fails. */
    if ((constants_registered && im2_cfstrings_clear()) ||
        (class_registration_started && im2_objc_registration_rollback(class_checkpoint))) {
        l_error("Registry cleanup failed; retaining image storage with execution blocked");
        image_raw = raw;
        return -1;
    }
    free(text_buf); text_buf = NULL;
    if (thunk_blk >= 0) sceKernelFreeMemBlock(thunk_blk);
    if (image_blk >= 0) sceKernelFreeMemBlock(image_blk);
    thunk_blk = image_blk = -1;
    thunk_head = thunk_end = NULL;
    free(raw);
    symtab = NULL; strtab = NULL; nsyms = strtab_size = 0;
    text_real = macho_slide = text_vm = text_size = data_vm = data_size = 0;
    code_vm = code_size = mod_init_addr = mod_init_count = 0;
    return -1;
}

static void invoke_initializer(void *context,uint32_t function) {
    (void)context;call_guest((void *)(uintptr_t)function,0,0,0,0);
}
int macho_run_inits(void) {
    if(!guest_exec_ready) return -1;
    if(!mod_init_count) return 0;
    if(!mod_init_addr) return -1;
    int result=im2_run_initializers((const uint32_t *)(uintptr_t)mod_init_addr,
        mod_init_count,macho_slide+code_vm,code_size,invoke_initializer,NULL);
    if(result) l_error("Constructor list rejected before guest execution");
    return result;
}
